import React, { useState } from 'react';
import styles from '../css/Weather.module.css';

const Weather = () => {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);
  const [loading, setLoading] = useState(false);

  const WEATHER_API_KEY = '7ac5efbe309f3e7a20018760eb67b567';
  const OPENAI_API_KEY = 'sk-k0sU6o1u_gKlLFaEmmgLdABqyY_KzA7x9pTe11fqoJT3BlbkFJLZi6JObdonvLwhD44tTUM-RyuKDROoEEC-94QXvH0A'; // OpenAI API 키 입력

  // OpenAI API를 사용하여 도시명을 영어로 변환
  const translateCityName = async (cityName) => {
    try {
      const response = await fetch('https://api.openai.com/v1/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${OPENAI_API_KEY}`,
        },
        body: JSON.stringify({
          model: 'gpt-4', // 올바른 모델 사용
          prompt: `"${cityName}"을 영어로 변환해주세요.`,
          max_tokens: 10,
          temperature: 0,
        }),
      });
  
      const data = await response.json();
      console.log('API 응답 데이터:', data); // 응답 전체를 출력
      const translation = data.choices && data.choices[0]?.text?.trim();
      return translation || cityName; // 응답 형식이 예상과 다를 경우 기본값 반환
    } catch (error) {
      console.error('도시명 변환 중 오류 발생:', error);
      return cityName; // 오류 발생 시 원래 도시명 반환
    }
  };

  const fetchWeather = async () => {
    if (!city) {
      alert('도시 이름을 입력하세요.');
      return;
    }

    setLoading(true);
    const translatedCity = await translateCityName(city);

    try {
      const response = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${translatedCity}&appid=${WEATHER_API_KEY}&units=metric&lang=kr`
      );
      const data = await response.json();
      console.log(data); // 데이터를 콘솔에 출력
      if (data.cod === 200) {
        setWeatherData(data);
      } else {
        alert('도시를 찾을 수 없습니다!');
        setWeatherData(null);
      }
    } catch (error) {
      console.error('날씨 데이터를 가져오는 중 오류가 발생했습니다:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2>날씨 정보</h2>
      <input
        className={styles.input}
        type="text"
        placeholder="도시 이름 입력"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button className={styles.button} onClick={fetchWeather}>
        {loading ? '불러오는 중...' : '날씨 정보 가져오기'}
      </button>
      {weatherData && (
        <div className={styles['weather-info']}>
          <p>온도: {Math.round(weatherData.main.temp)}°C</p>
          <p>날씨: {weatherData.weather[0].description}</p>
        </div>
      )}
    </div>
  );
};

export default Weather;
